          {
            "sha": "b8cdafdd",
            "full_sha": "b8cdafdd5a08a020bf6c5c6ef8597bbf8a2fe4d8",
            "date": "2026-07-06",
            "author": "mpfaffenberger",
            "subject": "fix(windows): make Shift+Enter insert a newline",
            "body": "Classic console input (msvcrt.getwch) encodes Shift+Enter as a bare \\r, byte-identical to plain Enter, and neither Windows Terminal nor conhost honors the xterm modifyOtherKeys arming that disambiguates it elsewhere (Ctrl+Enter only worked because the console encodes it as \\n, hitting the Ctrl+J path). The listener now polls the live Shift state via GetAsyncKeyState when a \\r arrives and synthesizes the CSI-u sequence (ESC[13;2u) the editor already maps to newline. Translation runs after paste coalescing so Shift+Insert pastes stay atomic; degrades to plain Enter on headless/remote sessions.",
            "theme": "misc",
            "kind": "fix",
            "impact": "notable",
            "summary": {
              "impact": "notable",
              "what": "Classic console input (msvcrt.getwch) encodes Shift+Enter as a bare \\r, byte-identical to plain Enter, and neither Windows Terminal nor conhost honors the xterm modifyOtherKeys arming that disambiguates it elsewhere (Ctrl+Enter only worked because the console encodes it as \\n, hitting the Ctrl+J path).",
              "why_rad": "Removes a rough edge.",
              "how_helps": "Translation runs after paste coalescing so Shift+Insert pastes stay atomic; degrades to plain Enter on headless/remote sessions."
            },
            "files": [
              "tests/agents/test_key_listener_posix_resilience.py"
            ],
            "file_count": 1,
            "is_version_bump": false,
            "bumped_version": "",
            "github_url": "https://github.com/mpfaffenberger/code_puppy/commit/b8cdafdd5a08a020bf6c5c6ef8597bbf8a2fe4d8"
          }
